"x":27,"y":15,"type":"stone"},{"x":28,"y":15,"type":"stone"},{"x":29,"y":15,"type":"stone"},{"x":30,"y":15,"type":"stone"},{"x":31,"y":15,"type":"stone"},{"x":32,"y":15,"type":"stone"},{"x":8,"y":24,"type":"stone"},{"x":9,"y":24,"type":"stone"},{"x":10,"y":24,"type":"stone"},{"x":11,"y":24,"type":"stone"},{"x":12,"y":24,"type":"stone"},{"x":13,"y":24,"type":"stone"},{"x":14,"y":24,"type":"stone"},{"x":15,"y":24,"type":"stone"},{"x":17,"y":24,"type":"stone"},{"x":18,"y":24,"type":"stone"},{"x":19,"y":24,"type":"stone"},{"x":20,"y":24,"type":"stone"},{"x":21,"y":24,"type":"stone"},{"x":22,"y":24,"type":"stone"},{"x":23,"y":24,"type":"stone"},{"x":24,"y":24,"type":"stone"},{"x":25,"y":24,"type":"stone"},{"x":26,"y":24,"type":"stone"},{"x":27,"y":24,"type":"stone"},{"x":28,"y":24,"type":"stone"},{"x":29,"y":24,"type":"stone"},{"x":30,"y":24,"type":"stone"},{"x":31,"y":24,"type":"stone"},{"x":24,"y":7,"type":"stone"},{"x":24,"y":8,"type":"stone"},{"x":24,"y":9,"type":"stone"},{"x":24,"y":10,"type":"stone"},{"x":24,"y":11,"type":"stone"},{"x":24,"y":12,"type":"stone"},{"x":24,"y":13,"type":"stone"},{"x":24,"y":14,"type":"stone"},{"x":18,"y":16,"type":"wood"},{"x":22,"y":16,"type":"wood"},{"x":18,"y":17,"type":"wood"},{"x":22,"y":17,"type":"wood"},{"x":18,"y":18,"type":"wood"},{"x":22,"y":18,"type":"wood"},{"x":18,"y":19,"type":"wood"},{"x":19,"y":19,"type":"wood"},{"x":20,"y":19,"type":"wood"},{"x":21,"y":19,"type":"wood"},{"x":22,"y":19,"type":"wood"}],"signLabels":{},"removedLand":[{"x":19,"y":16},{"x":20,"y":16},{"x":21,"y":16},{"x":19,"y":17},{"x":20,"y":17},{"x":21,"y":17},{"x":19,"y":18},{"x":20,"y":18},{"x":21,"y":18}]}'::jsonb;v_new jsonb;v_profile app_private.player_islands;v_normalized jsonb;v_layout jsonb;v_ids jsonb;v_doc jsonb;v_labels jsonb;v_item record;v_caption text;v_p jsonb;
begin
 select blueprint->'document' into v_new from public.island_starters where id='default';
 for v_profile in select * from app_private.player_islands order by user_id for update loop
  with mapped as(
   select p.value,p.ordinality,case when i.sale_value=0 then (select o->>'id' from jsonb_array_elements(v_old->'layout')o where split_part(o->>'id','~',1)=i.item_id and o-'id'=p.value-'id' limit 1) end origin
   from jsonb_array_elements(v_profile.document->'layout')with ordinality p(value,ordinality)
   left join app_private.player_island_items i on i.user_id=v_profile.user_id and i.id=p.value->>'id'
  )select coalesce(jsonb_agg(case when origin is not null then value||jsonb_build_object('id',origin) else value end order by ordinality),'[]'),coalesce(jsonb_object_agg(origin,value->>'id')filter(where origin is not null),'{}') into v_layout,v_ids from mapped;
  v_normalized:=jsonb_set(v_profile.document,'{layout}',v_layout);
  v_labels:=coalesce(v_profile.document->'signLabels','{}');
  if v_normalized-'signLabels'=v_old-'signLabels' and not exists(select 1 from jsonb_each_text(v_labels)e join jsonb_array_elements(v_profile.document->'layout')p on p->>'id'=e.key where p?'label' and p->>'label'<>e.value) then
   if exists(select 1 from jsonb_array_elements(v_new->'layout')p where p->>'id' not like '%~owned:%' and not(v_ids?(p->>'id'))) then raise exception 'STARTER_OWNERSHIP_REQUIRED';end if;
   select jsonb_agg(case when v_ids?(p->>'id') then p||jsonb_build_object('id',v_ids->>(p->>'id')) else p end order by ordinality) into v_layout from jsonb_array_elements(v_new->'layout')with ordinality x(p,ordinality);
   for v_p in select value from jsonb_array_elements(v_layout) where value?'label' loop v_labels:=v_labels||jsonb_build_object(v_p->>'id',v_p->>'label');end loop;
   v_doc:=v_new||jsonb_build_object('layout',v_layout,'signLabels',v_labels);
  else
   v_doc:=v_profile.document;
   for v_item in select id from app_private.player_island_items where user_id=v_profile.user_id and item_id='island-name-sign' and sale_value=0 loop
    v_caption:=case v_labels->>v_item.id when '교류' then '광장' when '낚시' then '바다' end;
    if v_caption is not null then v_labels:=v_labels||jsonb_build_object(v_item.id,v_caption);end if;
   end loop;
   select coalesce(jsonb_agg(case when p->>'label' in ('교류','낚시') and exists(select 1 from app_private.player_island_items i where i.user_id=v_profile.user_id and i.id=p->>'id' and i.item_id='island-name-sign' and i.sale_value=0) then p||jsonb_build_object('label',case p->>'label' when '교류' then '광장' else '바다' end) else p end order by ordinality),'[]') into v_layout from jsonb_array_elements(v_doc->'layout')with ordinality x(p,ordinality);
   v_doc:=v_doc||jsonb_build_object('layout',v_layout,'signLabels',v_labels);
  end if;
  if v_doc is distinct from v_profile.document then update app_private.player_islands set document=v_doc,revision=revision+1,updated_at=now() where user_id=v_profile.user_id;end if;
 end loop;
end $align$;
